/// A fresh identity: a P-256 key and a self-signed certificate over it
/// that never expires in practice (rcgen's default `not_after` is the
/// year 4096). Returns the identity and the key as PEM, which goes to
/// the Keychain and nowhere else. `server_id` is kept when given: a
/// rotated key is a new identity for clients but the same installation.
pub fn make_identity(
    server_id: Option<Uuid>,
    server_name: &str,
    listen: Listen,
) -> Result<(Identity, String), String> {
    let server_id = server_id.unwrap_or_else(Uuid::new_v4);
    fn remote_subscribe(
        &mut self,
        request: &RemoteRequest,
        device: uuid::Uuid,
        subscriber: Option<SubscriberQueue>,
    ) -> RemoteReply {
        let Some(queue) = subscriber.filter(|_| request.upgrade.is_some()) else {
            return self.refuse(
                request,
                400,
                "upgrade_required",
                "events are a WebSocket; upgrade the connection",
                true,
            );
        };
        let hello = self.event_json("hello", None, epoch_millis(SystemTime::now()));
        if queue.tx.try_send(hello).is_err() {
            return self.refuse(
                request,
                503,
                "busy",
                "the subscription could not start",
                true,
            );
        }
        self.subscribers.push(Subscriber {
            id: queue.id,
            queue,
            device,
            all: request.param("scope") == Some("all"),
        });
        RemoteReply {
            status: remote::SUBSCRIBED,
            body: Vec::new(),
            authenticated: true,
        }
    }

